			build_inv_iommu_pages(&cmd, address, size, gdom_info->hdom_id,
					      IOMMU_NO_PASID, false);
			ret |= iommu_queue_command(iommu, &cmd);
		}
		xa_unlock(&aviommu->gdomid_array);
	}
